// src/pages/account/MyPlaylists.js
import React, { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import api from "../../api";
import "./MyPlaylists.css";

/** Try multiple endpoints until one works and normalize shapes. */
async function getMyPlaylists() {
  const candidates = [
    "/playlists?mine=1&include_private=1",
    "/playlists?scope=me&include_private=1",
    "/playlists?include_private=1",
    "/playlists?mine=1",
    "/playlists?scope=me",
    "/playlists",
  ];
  for (const u of candidates) {
    try {
      const r = await api.get(u);
      let items =
        r.data?.playlists ??
        r.data?.items ??
        (Array.isArray(r.data) ? r.data : []);
      if (!Array.isArray(items)) items = [];
      return items;
    } catch (e) {
      const code = e?.response?.status;
      // keep trying on auth-ish errors; otherwise only throw on last attempt
      if (
        code !== 401 &&
        code !== 403 &&
        u === candidates[candidates.length - 1]
      )
        throw e;
    }
  }
  return [];
}

export default function MyPlaylists() {
  const [list, setList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [form, setForm] = useState({ title: "", is_public: true });

  const shareBase = useMemo(() => {
    if (typeof window !== "undefined")
      return `${window.location.origin}/playlists/`;
    return "/playlists/";
  }, []);

  async function load() {
    setLoading(true);
    setErr("");

    // Ensure Authorization header is present on hard refresh
    const token =
      localStorage.getItem("token") || sessionStorage.getItem("token");
    if (token && !api.defaults.headers.common.Authorization) {
      api.defaults.headers.common.Authorization = `Bearer ${token}`;
    }

    try {
      const items = await getMyPlaylists();
      setList(items);
    } catch (e) {
      setErr(
        e?.response?.data?.message || e.message || "Failed to load playlists",
      );
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function createPlaylist(e) {
    e.preventDefault();
    const title = form.title.trim();
    if (!title) return;
    try {
      const r = await api.post("/playlists", {
        title,
        is_public: !!form.is_public,
      });
      const created = r.data?.playlist ?? r.data;
      setList((x) => [created, ...x]);
      setForm({ title: "", is_public: true });
    } catch (e) {
      alert(e?.response?.data?.message || "Create failed");
    }
  }

  async function togglePublic(p) {
    try {
      const r = await api.put(`/playlists/${p.id}`, {
        is_public: !p.is_public,
      });
      const updated = r.data?.playlist ?? r.data;
      setList((xs) =>
        xs.map((x) => (x.id === p.id ? { ...x, ...updated } : x)),
      );
    } catch (e) {
      alert(e?.response?.data?.message || "Update failed");
    }
  }

  async function remove(id) {
    if (!window.confirm("Delete this playlist?")) return;
    try {
      await api.delete(`/playlists/${id}`);
      setList((xs) => xs.filter((x) => x.id !== id));
    } catch (e) {
      alert(e?.response?.data?.message || "Delete failed");
    }
  }

  async function copyShare(url) {
    try {
      await navigator.clipboard.writeText(url);
      alert("Link copied!");
    } catch {
      // no-op
    }
  }

  return (
    <div className="mp-page">
      <header className="mp-head">
        <div>
          <h1 className="mp-title">My Playlists</h1>
          <p className="mp-sub">
            Save messages to watch later, or share a playlist with others.
          </p>
        </div>
        <Link to="/catalog" className="mp-btn mp-btn--ghost">
          <span aria-hidden="true">←</span> Back to Catalog
        </Link>
      </header>

      <form className="mp-card mp-create" onSubmit={createPlaylist}>
        <label className="mp-field">
          <span className="mp-label">New playlist</span>
          <input
            className="mp-input"
            value={form.title}
            onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
            placeholder="Playlist name (e.g., Favorite Messages)"
          />
        </label>
        <label className="mp-switch">
          <input
            type="checkbox"
            checked={!!form.is_public}
            onChange={(e) =>
              setForm((f) => ({ ...f, is_public: e.target.checked }))
            }
          />
          <span className="mp-switchUi" aria-hidden="true" />
          <span>
            Public <small>(anyone with the link can view)</small>
          </span>
        </label>
        <button type="submit" className="mp-btn mp-btn--primary">
          Create playlist
        </button>
      </form>

      {loading && (
        <p className="mp-state" role="status">
          Loading…
        </p>
      )}
      {err && (
        <p className="mp-error" role="alert">
          {err}
        </p>
      )}

      {!loading && !err && list.length === 0 && (
        <div className="mp-empty">
          You don’t have any playlists yet. Use the form above to create one,
          then add videos from any video page using “Add to playlist”.
        </div>
      )}

      <ul className="mp-list">
        {list.map((p) => {
          const id = p?.id ?? p?.playlist_id;
          const slug = p?.slug;
          const shareUrl = slug ? shareBase + slug : shareBase + (id ?? "");
          const count =
            p.count ?? p.video_count ?? p.items_count ?? p.videos?.length ?? 0;

          return (
            <li key={id} className="mp-card mp-item">
              <div className="mp-itemIcon" aria-hidden="true">
                ▶
              </div>
              <div className="mp-itemMain">
                <div className="mp-itemTitle">{p.title || "Untitled"}</div>
                <div className="mp-itemMeta">
                  <span
                    className={`mp-badge ${p.is_public ? "is-public" : ""}`}
                  >
                    {p.is_public ? "Public" : "Private"}
                  </span>
                  {count} {count === 1 ? "video" : "videos"}
                </div>
                {p.is_public && (
                  <div className="mp-share">
                    <a href={shareUrl} target="_blank" rel="noreferrer">
                      {shareUrl}
                    </a>
                    <button
                      className="mp-btn mp-btn--mini"
                      type="button"
                      onClick={() => copyShare(shareUrl)}
                    >
                      Copy link
                    </button>
                  </div>
                )}
              </div>

              <div className="mp-actions">
                <Link
                  to={`/playlists/${slug || id}`}
                  className="mp-btn mp-btn--primary mp-btn--sm"
                >
                  Open
                </Link>
                <Link
                  to={`/account/playlists/${slug || id}/edit`}
                  className="mp-btn mp-btn--ghost mp-btn--sm"
                >
                  Edit
                </Link>
                <button
                  className="mp-btn mp-btn--ghost mp-btn--sm"
                  onClick={() => togglePublic(p)}
                >
                  {p.is_public ? "Make private" : "Make public"}
                </button>
                <button
                  className="mp-btn mp-btn--danger mp-btn--sm"
                  onClick={() => remove(id)}
                >
                  Delete
                </button>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
